seq = ""
with open("region.fasta") as f:
    for line in f:
        if not line.startswith(">"):
            seq += line.strip()
N=len(seq)
def rc(s): return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

# find perfect inverted repeats: stem length k>=5, loop between 3 and 25, allowing loop of any bases
repeats=[]
for k in range(5,10):
    d={}
    for i in range(N-k+1):
        sub=seq[i:i+k]
        key=rc(sub)
        if key in d:
            for j in d[key]:
                if i-j-k>=3 and i-j-k<=25:
                    repeats.append((j,i,k,i-j-k))
        d.setdefault(sub,[]).append(i)
# dedupe
seen=set(); out=[]
for r in sorted(repeats,key=lambda x:(x[0],-x[2])):
    key=(r[0],r[1])
    if key in seen: continue
    seen.add(key); out.append(r)
print("count",len(out))
for (i,j,k,loop) in out:
    print(f"stem {i}-{i+k} / {j}-{j+k} loop {loop}  seq {seq[i:j+k]}")
